from pathlib import Path


def replace_once(path: str, old: str, new: str):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'pattern not found in {path}: {old[:120]!r}')
    text = text.replace(old, new, 1)
    p.write_text(text, encoding='utf-8')

# Recovery must remain usable even when stable Web is missing/broken.
p = Path('windows/maintenance/src/Sokna.Maintenance.Core/ProductionLocalSlotMigration.cs')
text = p.read_text(encoding='utf-8')
text = text.replace(
'''    [property: JsonPropertyName("stable_web_root")] string StableWebRoot,\n    [property: JsonPropertyName("release_root")] string ReleaseRoot,''',
'''    [property: JsonPropertyName("stable_web_root")] string StableWebRoot,\n    [property: JsonPropertyName("apache_executable")] string ApacheExecutable,\n    [property: JsonPropertyName("health_url")] string HealthUrl,\n    [property: JsonPropertyName("release_root")] string ReleaseRoot,''', 1)
text = text.replace(
'''            layout.PackageRoot,\n            layout.WebRoot,\n            releaseRoot,''',
'''            layout.PackageRoot,\n            layout.WebRoot,\n            layout.ApacheExecutable,\n            layout.HealthUrl,\n            releaseRoot,''', 1)
old_recover = '''        var events = state.Events.ToList();\n        var layout = _discovery.DiscoverAndVerify(state.ExpectedBuild, state.ExpectedManagedFiles);\n        var currentTree = LocalManagedTreeAttestation.RequireExact(layout.WebRoot, state.ExpectedManagedFiles, state.ExpectedManagedTreeSha256);\n\n        // If the current stable Web is already healthy, recovery is reconciliation only.\n        try\n        {\n            RequireHttpHealth(state.ExpectedBuild, layout.HealthUrl);\n            state = state with { RecoveryRequired = false };\n            state = Event(state, events, layout.WebIsReparsePoint ? "RECOVERED_TO_VERIFIED_SLOT" : "RECOVERED_TO_PHYSICAL_WEB", layout.WebRoot);\n            return Result(state, currentTree);\n        }\n        catch (InvalidDataException)\n        {\n            // Continue into deterministic physical-Web restoration below.\n        }\n\n        var backup = state.PhysicalWebBackup;'''
new_recover = '''        var events = state.Events.ToList();\n\n        // Recovery must not require Local Web to be healthy. If the stable entry is present\n        // and healthy, reconcile state without mutation; otherwise restore from durable\n        // physical-Web backup using Apache/health facts captured before activation.\n        if (Directory.Exists(state.StableWebRoot))\n        {\n            try\n            {\n                var currentLayout = _discovery.DiscoverAndVerify(state.ExpectedBuild, state.ExpectedManagedFiles);\n                var currentTree = LocalManagedTreeAttestation.RequireExact(currentLayout.WebRoot, state.ExpectedManagedFiles, state.ExpectedManagedTreeSha256);\n                RequireHttpHealth(state.ExpectedBuild, currentLayout.HealthUrl);\n                state = state with { RecoveryRequired = false, ActiveSlot = currentLayout.ActiveSlotTarget };\n                state = Event(state, events, currentLayout.WebIsReparsePoint ? "RECOVERED_TO_VERIFIED_SLOT" : "RECOVERED_TO_PHYSICAL_WEB", currentLayout.WebRoot);\n                return Result(state, currentTree);\n            }\n            catch (Exception ex) when (ex is InvalidDataException or IOException or UnauthorizedAccessException)\n            {\n                state = Event(state, events, "RECOVERY_CURRENT_LAYOUT_UNHEALTHY", ex.Message);\n            }\n        }\n\n        var backup = state.PhysicalWebBackup;'''
if old_recover not in text:
    raise SystemExit('recover prologue pattern not found')
text = text.replace(old_recover, new_recover, 1)
old_block = '''        StopApacheAndProveExit(layout.ApacheExecutable);\n        state = Event(state, events, "RECOVERY_APACHE_STOPPED", backup);\n\n        if (Directory.Exists(layout.WebRoot))\n        {\n            var attributes = File.GetAttributes(layout.WebRoot);\n            if ((attributes & FileAttributes.ReparsePoint) != 0)\n            {\n                RemoveJunction(layout.WebRoot);\n            }\n            else\n            {\n                throw new IOException("Refusing recovery because stable Web is occupied by an unhealthy physical directory.");\n            }\n        }\n\n        Directory.Move(backup, layout.WebRoot);\n        StartApache();\n        RequireHttpHealth(state.ExpectedBuild, layout.HealthUrl);'''
new_block = '''        StopApacheAndProveExit(state.ApacheExecutable);\n        state = Event(state, events, "RECOVERY_APACHE_STOPPED", backup);\n\n        if (Directory.Exists(state.StableWebRoot))\n        {\n            var attributes = File.GetAttributes(state.StableWebRoot);\n            if ((attributes & FileAttributes.ReparsePoint) != 0)\n            {\n                RemoveJunction(state.StableWebRoot);\n            }\n            else\n            {\n                throw new IOException("Refusing recovery because stable Web is occupied by an unhealthy physical directory.");\n            }\n        }\n\n        Directory.Move(backup, state.StableWebRoot);\n        StartApache();\n        RequireHttpHealth(state.ExpectedBuild, state.HealthUrl);'''
if old_block not in text:
    raise SystemExit('recover restore block pattern not found')
text = text.replace(old_block, new_block, 1)
p.write_text(text, encoding='utf-8')

# Update Engine production commands.
engine = 'windows/maintenance/src/Sokna.Maintenance.UpdateEngine/Program.cs'
replace_once(engine,
'''    Console.WriteLine("SOKNA Maintenance Update Engine 0.3.2 (P3 R5 health/recovery hardening; DB mutation disabled)");''',
'''    Console.WriteLine("SOKNA Maintenance Update Engine 0.3.3 (R6 production Local migration bridge; DB mutation disabled)");''')
replace_once(engine,
'''    Console.WriteLine("local-slot-home-cycle --expected-build <id> --expected-managed-files <n> --expected-managed-tree-sha256 <sha256> [--data-root <path>]");''',
'''    Console.WriteLine("local-slot-migrate --expected-build <id> --expected-managed-files <n> --expected-managed-tree-sha256 <sha256> [--data-root <path>]");\n    Console.WriteLine("local-slot-recover [--data-root <path>]");\n    Console.WriteLine("local-slot-home-cycle --expected-build <id> --expected-managed-files <n> --expected-managed-tree-sha256 <sha256> [--data-root <path>] (engineering legacy)");''')
replace_once(engine,
'''if (command == "verify-stage")\n{\n    RequireOption(options, "--package", out var package);\n    RequireOption(options, "--identity", out var identity);\n    RunVerifyStage(package, identity, paths);\n    return;\n}\n\nRequireOption(options, "--expected-build", out var expectedBuild);''',
'''if (command == "verify-stage")\n{\n    RequireOption(options, "--package", out var package);\n    RequireOption(options, "--identity", out var identity);\n    RunVerifyStage(package, identity, paths);\n    return;\n}\n\nif (command == "local-slot-recover")\n{\n    try\n    {\n        var result = new ProductionLocalSlotMigrationBridge(paths).Recover();\n        Console.WriteLine(JsonSerializer.Serialize(new\n        {\n            ok = result.Ok,\n            engine_version = "0.3.3",\n            phase = result.Phase,\n            result,\n            managed_tree_sha256 = result.ManagedTreeSha256,\n            activation_performed = result.ActivationPerformed,\n            database_mutation_performed = false,\n            public_mutation_performed = false,\n            windows_reboot_required = false,\n            recovery_required = result.RecoveryRequired\n        }, AtomicFile.JsonOptions));\n    }\n    catch (Exception ex) when (ex is InvalidDataException or IOException or UnauthorizedAccessException or TimeoutException or AggregateException or System.ComponentModel.Win32Exception or InvalidOperationException)\n    {\n        Console.Error.WriteLine(JsonSerializer.Serialize(new\n        {\n            ok = false,\n            engine_version = "0.3.3",\n            phase = "RECOVERY_FAILED",\n            code = "LOCAL_SLOT_RECOVERY_FAILED",\n            error = ex.Message,\n            activation_performed = true,\n            database_mutation_performed = false,\n            public_mutation_performed = false,\n            windows_reboot_required = false,\n            recovery_required = true,\n            state_path = Path.Combine(paths.LocalSlotStateRoot, "migration-state.json")\n        }, AtomicFile.JsonOptions));\n        Environment.ExitCode = 4;\n    }\n    return;\n}\n\nRequireOption(options, "--expected-build", out var expectedBuild);''')
replace_once(engine,
'''        case "local-slot-home-cycle":\n        {''',
'''        case "local-slot-migrate":\n        {\n            var layout = slots.DiscoverAndVerify(expectedBuild, expectedManagedFiles);\n            var managedTree = LocalManagedTreeAttestation.RequireExact(layout.WebRoot, expectedManagedFiles, expectedManagedTreeSha256);\n            var result = new ProductionLocalSlotMigrationBridge(paths).Migrate(expectedBuild, expectedManagedFiles, expectedManagedTreeSha256);\n            Console.WriteLine(JsonSerializer.Serialize(new\n            {\n                ok = result.Ok,\n                engine_version = "0.3.3",\n                phase = result.Phase,\n                result,\n                managed_tree_sha256 = result.ManagedTreeSha256,\n                pre_activation_managed_tree_sha256 = managedTree,\n                activation_performed = result.ActivationPerformed,\n                database_mutation_performed = false,\n                public_mutation_performed = false,\n                windows_reboot_required = false,\n                recovery_required = result.RecoveryRequired\n            }, AtomicFile.JsonOptions));\n            break;\n        }\n        case "local-slot-home-cycle":\n        {''')
# All engine surfaces now report semantic 0.3.3.
p = Path(engine)
text = p.read_text(encoding='utf-8').replace('engine_version = "0.3.2"', 'engine_version = "0.3.3"')
text = text.replace('code = "LOCAL_SLOT_PHASE3_FAILED"', 'code = command == "local-slot-migrate" ? "LOCAL_SLOT_MIGRATION_FAILED" : "LOCAL_SLOT_PHASE3_FAILED"')
p.write_text(text, encoding='utf-8')

# Supervisor production endpoints and auth ownership.
supervisor = 'windows/maintenance/src/Sokna.Maintenance.Supervisor/Program.cs'
replace_once(supervisor,
'''var localSlotCoordinator = new SupervisorLocalSlotCoordinator(paths, operations, journal, state, updateEnginePath);''',
'''var localSlotCoordinator = new SupervisorLocalSlotCoordinator(paths, operations, journal, state, updateEnginePath);\nvar productionMigrationCoordinator = new SupervisorProductionMigrationCoordinator(paths, operations, journal, state, updateEnginePath);''')
replace_once(supervisor,
'''    var isStageMutation = HttpMethods.IsPost(context.Request.Method) && context.Request.Path.Equals("/v1/update/stage", StringComparison.Ordinal);\n    var isLocalSlotMutation = HttpMethods.IsPost(context.Request.Method) && context.Request.Path.Equals("/v1/local-slots/home-cycle", StringComparison.Ordinal);\n    var isMutation = isStageMutation || isLocalSlotMutation;''',
'''    var isStageMutation = HttpMethods.IsPost(context.Request.Method) && context.Request.Path.Equals("/v1/update/stage", StringComparison.Ordinal);\n    var isLocalSlotMutation = HttpMethods.IsPost(context.Request.Method) && context.Request.Path.Equals("/v1/local-slots/home-cycle", StringComparison.Ordinal);\n    var isProductionMigration = HttpMethods.IsPost(context.Request.Method) && context.Request.Path.Equals("/v1/local-slots/migrate", StringComparison.Ordinal);\n    var isProductionRecovery = HttpMethods.IsPost(context.Request.Method) && context.Request.Path.Equals("/v1/local-slots/recover", StringComparison.Ordinal);\n    var isMutation = isStageMutation || isLocalSlotMutation || isProductionMigration || isProductionRecovery;''')
replace_once(supervisor,
'''            new { allowed_methods = new[] { "GET", "POST /v1/update/stage", "POST /v1/local-slots/home-cycle" }, activation_enabled = true, database_mutation_enabled = false });''',
'''            new { allowed_methods = new[] { "GET", "POST /v1/update/stage", "POST /v1/local-slots/migrate", "POST /v1/local-slots/recover", "POST /v1/local-slots/home-cycle" }, activation_enabled = true, database_mutation_enabled = false });''')
replace_once(supervisor,
'''    if (isLocalSlotMutation && keyId is not ("web-adapter" or "recovery-console"))\n    {\n        await WriteEnvelope(context, StatusCodes.Status403Forbidden, false, "forbidden", "LOCAL_SLOT_AUTHORITY_REQUIRED", false, new { });\n        return;\n    }\n\n    if ((isStageMutation || (isLocalSlotMutation && keyId == "web-adapter")) && aclEvidence.State != "ready")''',
'''    if (isLocalSlotMutation && keyId is not ("web-adapter" or "recovery-console"))\n    {\n        await WriteEnvelope(context, StatusCodes.Status403Forbidden, false, "forbidden", "LOCAL_SLOT_AUTHORITY_REQUIRED", false, new { });\n        return;\n    }\n    if (isProductionMigration && keyId != "web-adapter")\n    {\n        await WriteEnvelope(context, StatusCodes.Status403Forbidden, false, "forbidden", "WEB_ADAPTER_KEY_REQUIRED", false, new { });\n        return;\n    }\n    if (isProductionRecovery && keyId != "recovery-console")\n    {\n        await WriteEnvelope(context, StatusCodes.Status403Forbidden, false, "forbidden", "RECOVERY_CONSOLE_KEY_REQUIRED", true, new { });\n        return;\n    }\n\n    if ((isStageMutation || isProductionMigration || (isLocalSlotMutation && keyId == "web-adapter")) && aclEvidence.State != "ready")''')
insert_anchor = '''app.MapPost("/v1/local-slots/home-cycle", async context =>\n{'''
production_endpoints = '''app.MapPost("/v1/local-slots/migrate", async context =>\n{\n    if (!TrySingleHeader(context, HmacProtocol.HeaderIdempotencyKey, out var idempotencyKey))\n    {\n        await WriteEnvelope(context, StatusCodes.Status400BadRequest, false, "rejected", "IDEMPOTENCY_KEY_REQUIRED", false, new { });\n        return;\n    }\n    try\n    {\n        var body = context.Items[SignedBodyItem] as byte[] ?? Array.Empty<byte>();\n        var request = JsonSerializer.Deserialize<ProductionLocalSlotMigrationRequest>(body, AtomicFile.JsonOptions)\n                      ?? throw new InvalidDataException("Production migration request body is empty.");\n        var result = productionMigrationCoordinator.Migrate(request.ExpectedBuild, request.ExpectedManagedFiles, request.ExpectedManagedTreeSha256, request.OperatorId, idempotencyKey);\n        var operation = result.Operation;\n        var success = operation.State == "committed";\n        var recoveryRequired = operation.State == "recovery_required";\n        var statusCode = success ? StatusCodes.Status200OK : recoveryRequired ? StatusCodes.Status503ServiceUnavailable : operation.State is "running" or "accepted" ? StatusCodes.Status202Accepted : StatusCodes.Status422UnprocessableEntity;\n        await WriteEnvelope(context, statusCode, success, operation.State, operation.ResultCode ?? (success ? "LOCAL_SLOT_MIGRATION_COMMITTED" : "OPERATION_RECORDED"), recoveryRequired,\n            new { operation, result.Created, result.Reconciled, production_migration = true, database_mutation_enabled = false, public_mutation_enabled = false, windows_reboot_required = false }, operation.OperationId);\n    }\n    catch (JsonException ex)\n    {\n        await WriteEnvelope(context, StatusCodes.Status400BadRequest, false, "rejected", "REQUEST_JSON_INVALID", false, new { error = ex.Message });\n    }\n    catch (InvalidDataException ex)\n    {\n        var code = ex.Message.Contains("Idempotency key was already used", StringComparison.Ordinal) ? "IDEMPOTENCY_CONFLICT" : "REQUEST_INVALID";\n        await WriteEnvelope(context, code == "IDEMPOTENCY_CONFLICT" ? StatusCodes.Status409Conflict : StatusCodes.Status400BadRequest, false, "rejected", code, false, new { error = ex.Message });\n    }\n});\n\napp.MapPost("/v1/local-slots/recover", async context =>\n{\n    if (!TrySingleHeader(context, HmacProtocol.HeaderIdempotencyKey, out var idempotencyKey))\n    {\n        await WriteEnvelope(context, StatusCodes.Status400BadRequest, false, "rejected", "IDEMPOTENCY_KEY_REQUIRED", true, new { });\n        return;\n    }\n    try\n    {\n        var body = context.Items[SignedBodyItem] as byte[] ?? Array.Empty<byte>();\n        var request = JsonSerializer.Deserialize<ProductionLocalSlotRecoveryRequest>(body, AtomicFile.JsonOptions)\n                      ?? throw new InvalidDataException("Production recovery request body is empty.");\n        var result = productionMigrationCoordinator.Recover(request.OperatorId, idempotencyKey);\n        var operation = result.Operation;\n        var success = operation.State == "committed";\n        await WriteEnvelope(context, success ? StatusCodes.Status200OK : StatusCodes.Status503ServiceUnavailable, success, operation.State, operation.ResultCode ?? "LOCAL_SLOT_RECOVERY_FAILED", !success,\n            new { operation, result.Created, result.Reconciled, production_recovery = true, database_mutation_enabled = false, public_mutation_enabled = false, windows_reboot_required = false }, operation.OperationId);\n    }\n    catch (JsonException ex)\n    {\n        await WriteEnvelope(context, StatusCodes.Status400BadRequest, false, "rejected", "REQUEST_JSON_INVALID", true, new { error = ex.Message });\n    }\n    catch (InvalidDataException ex)\n    {\n        await WriteEnvelope(context, StatusCodes.Status400BadRequest, false, "rejected", "REQUEST_INVALID", true, new { error = ex.Message });\n    }\n});\n\n'''
p = Path(supervisor)
text = p.read_text(encoding='utf-8')
if insert_anchor not in text:
    raise SystemExit('supervisor endpoint anchor not found')
text = text.replace(insert_anchor, production_endpoints + insert_anchor, 1)
# Recovery status uses production migration state when present; legacy Phase3 remains fallback only.
old_recovery = '''    var current = AtomicFile.ReadJson<SupervisorState>(paths.StatePath);\n    var slotRecovery = false;\n    try { if (File.Exists(paths.LocalSlotStatePath)) slotRecovery = AtomicFile.ReadJson<LocalSlotPhase3State>(paths.LocalSlotStatePath).RecoveryRequired; } catch { slotRecovery = true; }\n    var recoveryRequired = current.RecoveryRequired || slotRecovery;'''
new_recovery = '''    var current = AtomicFile.ReadJson<SupervisorState>(paths.StatePath);\n    var slotRecovery = false;\n    var productionStatePath = Path.Combine(paths.LocalSlotStateRoot, "migration-state.json");\n    try\n    {\n        if (File.Exists(productionStatePath)) slotRecovery = AtomicFile.ReadJson<ProductionLocalSlotMigrationState>(productionStatePath).RecoveryRequired;\n        else if (File.Exists(paths.LocalSlotStatePath)) slotRecovery = AtomicFile.ReadJson<LocalSlotPhase3State>(paths.LocalSlotStatePath).RecoveryRequired;\n    }\n    catch { slotRecovery = true; }\n    var recoveryRequired = current.RecoveryRequired || slotRecovery;'''
if old_recovery not in text:
    raise SystemExit('supervisor recovery status anchor not found')
text = text.replace(old_recovery, new_recovery, 1)
# Health surface identifies production bridge capability.
text = text.replace('local_slot_phase = "p3",', 'local_slot_phase = "production_bridge_r6",', 1)
text = text.replace('["p3_local_slots_enabled"] = true,', '["production_local_slot_migration_enabled"] = true,', 1)
text = text.replace('["p3_local_slots_enabled"] = true,', '["production_local_slot_migration_enabled"] = true,', 1)
p.write_text(text, encoding='utf-8')

# Semantic component version bumps. Core stays internal but advances independently.
for path, old, new in [
    ('windows/maintenance/src/Sokna.Maintenance.Core/Sokna.Maintenance.Core.csproj', '0.2.1', '0.2.2'),
    ('windows/maintenance/src/Sokna.Maintenance.Supervisor/Sokna.Maintenance.Supervisor.csproj', '0.3.2', '0.3.3'),
    ('windows/maintenance/src/Sokna.Maintenance.UpdateEngine/Sokna.Maintenance.UpdateEngine.csproj', '0.3.2', '0.3.3'),
]:
    q = Path(path)
    t = q.read_text(encoding='utf-8').replace(old, new).replace('4.0.0-p3-r5-health-recovery-hardening', '4.0.0-r6-production-local-migration-bridge')
    q.write_text(t, encoding='utf-8')

print('R6 production Local migration bridge source patch applied')
